theorem.raw:
\label{thm:Hnotminimal}
 The subRiemannian Heisenberg group 
  is not minimal in looking down.

\label{thm:Heisenbergdistance}
Let $(\mathbb H, d_{cc})$ be the subRiemannian Heisenberg group.
There exists a distance $d$ on $\mathbb H $ such that
\begin{enumerate}
\item $d\leq d_{cc}$;
\item $(\mathbb H, d)$ is Ahlfors 4-regular;
\item if $A\subseteq \mathbb H$ is a subset with $\mathcal H^4_{cc}(A)>0$, then 
$d$ and $d_{cc}$ are not biLipschitz equivalent on $A$.
\end{enumerate}

\label{thm:general}
Let $(X,\rho)$ be a metric space and $Q>0$.
Assume 
\begin{enumerate}
\item $(X,\rho)$ is Ahlfors $Q$-regular;
 \item there exists $\lambda\in(0,1)$ such that
 for all $p\in X$ and all $0 < r < \operatorname{diam}(X)$ there exist $q_1, q_2\in B_\rho (p,r)$ such that
 $$\rho(q_1, q_2) \geq 
 \lambda r$$
 and
 \begin{equation}\label{e:general-metric-assumption}
 \rho(p_1, p_2) \leq \rho (p_1, q_1) + \rho (p_2, q_2), \qquad \forall p_1, p_2 \notin B_\rho (p,r).  
 \end{equation} 
\end{enumerate}
Then there exists a distance $d$ on $X $ such that
\begin{enumerate}
\item $d\leq \rho$;
\item $(X, d)$ is Ahlfors $Q$-regular;
\item if $A\subseteq X$ is a subset with $\mathcal H^Q_{\rho}(A)>0$, then 
$d$ and $\rho$ are not biLipschitz equivalent on $A$.
\end{enumerate}

\label{thm:fail}
There exist two distances $d_1, d_2$ on $\mathbb H $ that are biLipschitz equivalent to $d_{cc}$ such that
\begin{enumerate}
\item The distance $d_1$ is left-invariant, but no blow-up of $d_1$ is self-similar.
\item No blow-up of $d_2$ is left-invariant nor self-similar.
\end{enumerate}

