\label{lma:multiplicity}
  For any ${\bf x} \in {\mathcal I}_A$, there exists ${\bf x}' \in {\mathcal I}^*$ such that $\Ext({\bf x}) = \Ext({\bf x}')$, $c({\bf x}') \leq c({\bf x})$, and
  \begin{equation}
    \# L_{{\bf x}'}^{-1}(k) \leq 4, \qquad \forall k \in \mathbb N. \label{e:4-bound}
  \end{equation}
  Moreover, ${\bf x}$ and ${\bf x}'$ have the same first and last shortcuts.

\label{lma:largegaps}
 Let $x \in X$ and $0 < r < \lambda^n$.  There exists at most one pair $\{q_1,q_2\}$ such that
 $(q_1,q_2) \in {\mathcal S}$, $L(q_1,q_2) < n$ and $\{q_1,q_2\} \cap B_d(x,r) \ne \emptyset$.

\label{lma:inclusions}
 For all $x \in X$ and $r > 0$ there exist $y_1,y_2 \in X$ such that
 \begin{equation}\label{eq:inclusions}
  B_\rho(x,r) \subseteq B_d(x,r)  \subseteq B_\rho\left(\{y_1,y_2\},\left(2 + 8/(\lambda -\lambda^2)\right)r\right).
 \end{equation}

\label{lma:K-c1}
  There exists some absolute constant $c_E > 0$ so that






  \begin{equation}\label{e:K-ball-ind}
   K \subseteq \bigcup_{\mathtt{i} \in \{1,\dots,16\}^{n-3}} B_{d_b}(S_{\mathtt{i}}(\frac12,\frac12,0),c_E 2^{-n}), \qquad \forall n \geq 3.
  \end{equation}

There exists some $C > 0$ so that 
 for all multi-indices ${\mathtt{i}}$,
    for all $x,y \in S_{\mathtt{i}}(K)$ and all $\epsilon > 0$, there exists an itinerary ${\bf x} = (x_0,\dots,x_n) \in {\mathcal I}^*$ such that $c({\bf x}) \leq (1+\epsilon) d(x,y)$, $\Ext({\bf x}) = (x,y)$, and $x_0,\dots,x_n\in B_{d_b}(S_{\mathtt{i}}(K),C 2^{-|\mathtt{i}|})$.

Let $\mathtt{j}$ be from Lemma~\ref{lma:j-defn}.  Then for all $k \in \mathbb N$ and $\mathtt{i} \in \{1,\dots,16\}^k$, we have that
   \begin{equation}
     d(S_{\mathtt{i}}(x),S_{\mathtt{i}}(y)) = 2^{-|\mathtt{i}|} d(x,y), \qquad \forall x,y \in S_{\mathtt{j}}(K). \label{e:j-invariance}
   \end{equation}

\label{lma:norepeat}
  Let $\ell \geq 1$.  There exists some $m \geq 1$ so that for any $i \geq 1$,
  there exists some $j \in \{i,i+1,\dots,i + m\ell\}$ such that $a(j) \neq a(j+m\ell)$.

\label{lma:uniformlowerbounds-1}
 There exists a continuous function $f \colon [1,4] \to [\frac12,1]$ with the properties that
 $f(t)>\frac12$ for all $t \in (1,4)$ and 
 \begin{equation}
  d_1(0,(0,0,t4^{-n})) \ge f(t) d_{cc}(0,(0,0,t4^{-n})) \label{e:f-lower-bound}
 \end{equation}
 for all $n \in \mathbb N$ and $t \in (1,4)$.

\label{lma:uniformlowerbounds-2}
  For all $n \in a^{-1}(\{0\})$ and $t \in (\frac{1}{2},2)$, we have that
  \begin{equation}
    d_1(0,(0,0,t4^{-n})) \ge \frac{1}{\sqrt{3}} d_{cc}(0,(0,0,t4^{-n})). \label{e:sqrt3-lower}
  \end{equation}

