For the itinerary ${\bf x} = (x_0,\dots,x_N)$, we define $d_k = x_i^{-1}x_{i-1}$.  Let
  $$A = \{k : d_k \in {\rm Z}({\mathbb H})\}.$$
  We can define a bijection $\sigma : \{1,\dots,N\} \to \{1,\dots,N\}$ that maps $\{1,\dots,|A|\}$ to $A$ and preserves the ordering of $A^c$ (thus, we shift $A$ to the beginning in any order).  We now define the itinerary $(y_0,\dots,y_{|A|+1})$ where $y_0 = 0$, $y_{|A|+1} = x_N$, and $y_i = d_{\sigma(1)} \cdots d_{\sigma(i)}$.  As we only rearranged elements that are in the center, we get that $y_{|A|+1}^{-1}y_{|A|}$ is precisely the product (in order) of all the noncentral elements of $d_k$ and is itself central.

  It remains to show that $c({\bf y}) \leq c({\bf x})$.  We have that
  \begin{equation}
    c(x_{k-1},x_k) = c(y_{\sigma^{-1}(k)-1},y_{\sigma^{-1}(k)}), \qquad \forall k \in A. \label{e:A-c}
  \end{equation}
  As $d_k \notin {\rm Z}({\mathbb H})$ for $k \notin A$, we get that $(x_{k-1},x_k) \notin {\mathcal S}$ for $k \notin A$ and so
  \begin{equation}
    \sum_{k \notin A} c(x_{k-1},x_k) = \sum_{k \notin A} d_{cc}(x_{k-1},x_k) \geq d_{cc}(y_{|A|},y_{|A|+1}) \geq c(y_{|A|},y_{|A|+1}). \label{e:Ac-c}
  \end{equation}
  Thus, by 
  \eqref{e:A-c} and \eqref{e:Ac-c}
  we get that
  \[
    c({\bf y}) = \sum_{k=1}^{|A|+1} c(y_{k-1},y_k) 

    \leq
    \sum_{k=1}^N c(x_{k-1},x_k) = c({\bf x}).
  \]

Assume to the contrary that there exists a sequence $(\lambda_j)_{j \in \mathbb N}$, with $\lambda_j \to 0$ such that the distances
$$(p,q)\mapsto \dfrac{1}{\lambda_j} d_1(\delta_{\lambda_j} (p),\delta_{\lambda_j} (q)) $$
converge pointwise to some $\rho$, and the distance $\rho$ is self-similar with some constant $\lambda > 1$. 

 Let us now find a contradiction by using the assumed self-similarity.
 For this purpose let us first take a point $(0,0,s^2) \in \mathbb H$ appearing as limit of points to which there is a shortcut from the origin.
 In other words, take
 \begin{equation}\label{14598015}
  s \in [1,2^4] \cap \bigcap_{j=1}^\infty\overline{\bigcup_{i \geq j} \{\lambda_i^{-1}2^{-4(k+1)}\,:\, k \in \mathbb N\}}.
 \end{equation}
 Then we indeed have
 \[
  \rho(0,(0,0,s^2)) = \lim_{j \to \infty}\frac{1}{\lambda_j}d_1(0,(0,0,\lambda_j^2s^2)) = \frac12d_{cc}(0,(0,0,s^2)),
 \]
 since $a(4(k+1))= 1$ for all $k \in \mathbb N$.

 Let us then use the function $f$ of Lemma~\ref{lma:uniformlowerbounds-1}
 to show that there exists $\ell \in \mathbb N$ such that $\lambda  = 2^\ell$.
 Supposing this is not the case, we have $\lambda = t2^\ell$ for some $t \in (1,2)$ and $\ell \in \mathbb N$.
 By \eqref{14598015} $s$ is of the form $s=\lim_{m\to \infty} \lambda_{i_m}^{-1} 2^{-4(k_m+1)}$, with $i_m, k_m\to \infty$.
 Then, by the continuity of the function $f$ we have
 \begin{eqnarray*}
  \rho(0,(0,0,\lambda^2s^2)) & = &\lim_{j  \to \infty}\frac{1}{\lambda_j}d_1(0,(0,0,\lambda^2\lambda_j^2s^2))\\
& = &\lim_{m  \to \infty}\frac{1}{\lambda_{i_m}} 
d_1(0,(0,0,  t^2 
\left(  \dfrac{\lambda_{i_m} s}{ 2^{-4(k_m+1)}}\right)^2  
 4^\ell  4^{-4(k_m+1)}\lambda^2\lambda_j^2s^2))
\\
  & \ge& 
  \lim_{m  \to \infty}\frac{1}{\lambda_{i_m}} 
 f\left(t^2   \left(  \dfrac{\lambda_{i_m} s}{ 2^{-4(k_m+1)}}\right)^2\right ) d_{cc}(0,(0,0,\lambda^2\lambda_j^2s^2))\\
&=&  f(t^2)\lim_{j  \to \infty}\frac{1}{\lambda_j}d_{cc}(0,(0,0,\lambda^2\lambda_j^2s^2))\\
  & = &f(t^2)\lambda d_{cc}(0,(0,0,s^2)) > \frac12\lambda d_{cc}(0,(0,0,s^2)) = \lambda \rho(0,(0,0,s^2))
  ,
 \end{eqnarray*}
 contradicting the fact that $\rho$ is self-similar with the dilation $\lambda$.

 Therefore $\lambda = 2^\ell$ for some $\ell \in \mathbb N$. Now we employ the properties of the function $a$.
 Let $m \in \mathbb N$ be the constant from Lemma~\ref{lma:norepeat}. Since $\rho$ is self-similar with factor $2^\ell$,
 it is self-similar also with factor $2^{\ell m}$.
 By Lemma~\ref{lma:uniformupperbound}, we have that there exists some $\eta$ such that $(1+\eta)^N = 4$ for some $N \in \mathbb N$ and if $a(n) = 1$, then
 \begin{equation}
   d_1(0,(0,0,(1+t)4^{-n})) \leq 0.51 d_{cc}(0,(0,0,(1+t)4^{-n})), \qquad \forall t \in (-\eta,\eta). \label{e:upperbound}
 \end{equation}

 Take $j_0 \in \mathbb N$ such that for all $j \ge j_0$ we have
 \begin{equation}
  \frac{\rho(0,(0,0,4^i(1+\eta)^ks^2))}{\lambda_j^{-1} d_1(0,(0,0,4^i(1+\eta)^k\lambda_j^2s^2))} \in \left(1 - \frac{1}{100}, 1 + \frac{1}{100} \right), \label{e:precision}
 \end{equation}
 for all $(i,k) \in \{0,1,\dots,2 m\ell\} \times \{0,\dots,N-1\}$.  Let $n \in \mathbb Z$ be such that $(\lambda_j s)^2 \in \left[ \frac{1}{2} 4^{-n}, 2 \cdot 4^{-n}\right)$.  By Lemma~\ref{lma:norepeat}, we have that there exists some $i \in \{0,\dots,m \ell\}$ such that $a(n+i) \neq a(n+ i + m\ell)$.  We may suppose without loss of generality that $a(n+i) = 1$ so $a(n+i+m\ell) = 0$.

 We have that there exists some $k \in \{0,\dots,N-1\}$ such that $4^i(1+\eta)^k \lambda_j^2 s^2 \in ((1-\eta) 4^{n+i},(1+\eta) 4^{n+i})$.  Thus, because $a(n+i) = 1$, we have that
 \begin{equation}\label{eq:finalcontra}
    \rho(0,(0,0,4^i (1+\eta)^k s^2)) \overset{\eqref{e:upperbound} \wedge \eqref{e:precision}}{\leq} 0.52 d_{cc}(0,(0,0,4^i (1+\eta)^k s^2)).
 \end{equation}
 On the other hand, because $a(n+i+m\ell) = 0$ and $$4^{i+m\ell}(1+\eta)^k \lambda_j^2 s^2 \in \left( \frac{1}{2} 4^{n+i+m\ell}, 2 \cdot 4^{n+i+m\ell} \right),$$ we have that
 \begin{eqnarray*}
   \rho(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2)) &\overset{\eqref{e:sqrt3-lower} \wedge \eqref{e:precision}}{\geq} &\frac{99}{100} \frac{1}{\sqrt{3}} d_{cc}(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2)) \\
   &\geq& 0.55 d_{cc}(0,(0,0,4^{i+m\ell}(1+\eta)^k s^2)), \\
   &=& 0.55 \cdot 2^{m\ell} d_{cc}(0,(0,0,4^i(1+\eta)^k s^2)).
 \end{eqnarray*}
 Then by the self-similarity of $\rho$ with ratio $2^{m\ell}$ we have
  \begin{eqnarray*}
   \rho(0,(0,0,4^i (1+\eta)^k s^2)) & = & 2^{-m\ell}\rho(0,(0,0,4^{i+m\ell} (1+\eta)^k s^2))\\
   & \ge & 0.55 d_{cc}(0,(0,0,4^i(1+\eta)^k s^2)).
  \end{eqnarray*}
  This contradicts \eqref{eq:finalcontra}.

